import sys
import splunk.pdf.pdfgen_utils as pdfgen_utils
from splunk.clilib.bundle_paths import make_splunkhome_path
from splunk.rest.splunk_web_requests import get_dashboard_studio_settings, get_pdfgen_settings

logger = pdfgen_utils.getLogger()

sys.path.append(make_splunkhome_path(
    ['etc', 'apps', 'splunk-visual-exporter', 'bin']))
sys.path.append(make_splunkhome_path(
    ['etc', 'apps', 'splunk-visual-exporter', 'bin', 'modules']))


def get_chromium_engine():
    try:
        from export_utils.chromium.engine import ChromiumEngine
        return ChromiumEngine()
    except ImportError as err:
        logger.error(err)
        logger.error('Visual Exporter App is not installed')
        return None

def get_formatted_feature_flags(sessionKey=None):
    dashboard = get_dashboard_studio_settings(sessionKey)
    pdfgen = get_pdfgen_settings(sessionKey)

    return {
        'feature:dashboard_studio': dashboard,
        'feature:pdfgen': pdfgen
    }


def get_screenshot(definition, theme="light", sessionKey=None, studioErrors=None, timeout=None, screenshotDelay=None, exportMaxFileSizeMB=None, exportMaxScaleFactor=None, fileFormat="pdf"):
    '''
    Uses the chromium engine at etc/apps/splunk-visual-exporter/bin/utils/chromium/engine.py to take a screenshot of a dashboard

    Returns False if the app is not installed
    '''
    engine = get_chromium_engine()
    if (engine is None):
        return False
    
    feature_flags = get_formatted_feature_flags(sessionKey)

    if studioErrors == None:
        studioErrors = []

    return engine.get_screenshot(definition, theme, feature_flags, studioErrors, timeout, screenshotDelay, export_max_file_size_mb=exportMaxFileSizeMB, export_max_scale_factor=exportMaxScaleFactor, file_format=fileFormat)

def get_svg(dashboardName, viz, data, width=None, height=None, sxmlErrors=None, timeout=None):
    '''
    Uses the chromium engine at etc/apps/splunk-visual-exporter/bin/utils/chromium/engine.py to take a screenshot of a dashboard

    Returns False if the app is not installed
    '''
    engine = get_chromium_engine()
    if (engine is None):
        return False

    if sxmlErrors == None:
        sxmlErrors = []

    return engine.get_svg(dashboardName, viz, data, width, height, sxmlErrors, timeout)